export const vehicleTypes=["รย.12-น้อยกว่า 300cc","รย.12-300-799cc","รย.12-800-999cc","รย.12-1000cc ขึ้นไป","รย.1-เก๋ง 2 ตอน","รย.1-นั่ง 2 ตอน","รย.1-นั่ง 3 ตอน","รย.2-นั่ง 2 แถว","รย.2-นั่ง 4 ตอน","รย.3-กระบะบรรทุก","รย.3-กระบะบรรทุกมีหลังคา","รย.3-กระบะบรรทุกมีหลังคาแหนบ","รย.3-ตู้บรรทุก"];
// Province names: Ministry of Commerce, referencing DOPA, https://std.moc.go.th/std/group/28
export const provinces=['กรุงเทพมหานคร','สมุทรปราการ','นนทบุรี','ปทุมธานี','พระนครศรีอยุธยา','อ่างทอง','ลพบุรี','สิงห์บุรี','ชัยนาท','สระบุรี','ชลบุรี','ระยอง','จันทบุรี','ตราด','ฉะเชิงเทรา','ปราจีนบุรี','นครนายก','สระแก้ว','นครราชสีมา','บุรีรัมย์','สุรินทร์','ศรีสะเกษ','อุบลราชธานี','ยโสธร','ชัยภูมิ','อำนาจเจริญ','บึงกาฬ','หนองบัวลำภู','ขอนแก่น','อุดรธานี','เลย','หนองคาย','มหาสารคาม','ร้อยเอ็ด','กาฬสินธุ์','สกลนคร','นครพนม','มุกดาหาร','เชียงใหม่','ลำพูน','ลำปาง','อุตรดิตถ์','แพร่','น่าน','พะเยา','เชียงราย','แม่ฮ่องสอน','นครสวรรค์','อุทัยธานี','กำแพงเพชร','ตาก','สุโขทัย','พิษณุโลก','พิจิตร','เพชรบูรณ์','ราชบุรี','กาญจนบุรี','สุพรรณบุรี','นครปฐม','สมุทรสาคร','สมุทรสงคราม','เพชรบุรี','ประจวบคีรีขันธ์','นครศรีธรรมราช','กระบี่','พังงา','ภูเก็ต','สุราษฎร์ธานี','ระนอง','ชุมพร','สงขลา','สตูล','ตรัง','พัทลุง','ปัตตานี','ยะลา','นราธิวาส'].sort((a,b)=>a.localeCompare(b,'th'));
export const vehicleColumns=[['date','วันที่'],['customerId','ชื่อลูกค้า'],['chassis','เลขตัวถัง'],['engine','เลขเครื่อง'],['brandId','ยี่ห้อ'],['fuel','ประเภทเชื้อเพลิง'],['cc','ขนาด CC'],['weight','น้ำหนักรถ'],['color','สี'],['body','ประเภทรถ'],['registrationProvince','จังหวัดที่จดทะเบียน'],['ownerProvince','จังหวัดเจ้าของรถ']];
export function normalizeVehicle(input){return Object.fromEntries(vehicleColumns.map(([k])=>[k,String(input?.[k]??'').trim()]))}
export function vehicleErrors(v){const errors=[];if(v.body&&!vehicleTypes.includes(v.body))errors.push("กรุณาเลือกประเภทรถจากรายการที่กำหนด");if(!/^\d{4}-\d{2}-\d{2}$/.test(v.date)||!Number.isFinite(Date.parse(v.date))||new Date(v.date).toISOString().slice(0,10)!==v.date||Number(v.date.slice(0,4))<1900||Number(v.date.slice(0,4))>2100)errors.push('วันที่ต้องเป็น ค.ศ. YYYY-MM-DD ที่ถูกต้อง');if(!v.customerId)errors.push('กรุณาเลือกลูกค้า');if(!v.chassis)errors.push('กรุณากรอกเลขตัวถัง');if(!v.brandId)errors.push('กรุณาเลือกยี่ห้อ');for(const [key,label]of vehicleColumns){if(v[key].length>250)errors.push(label+'ยาวเกิน 250 ตัวอักษร')}for(const k of ['cc','weight'])if(v[k]!==''&&(!/^\d+(\.\d+)?$/.test(v[k])||!Number.isFinite(Number(v[k]))||Number(v[k])<0))errors.push(k==='cc'?'ขนาด CC ต้องเป็นตัวเลขตั้งแต่ 0':'น้ำหนักรถต้องเป็นตัวเลขตั้งแต่ 0');for(const k of ['registrationProvince','ownerProvince'])if(v[k]&&!provinces.includes(v[k]))errors.push(k==='registrationProvince'?'จังหวัดที่จดทะเบียนไม่ถูกต้อง':'จังหวัดเจ้าของรถไม่ถูกต้อง');return errors}
